//! LED0 (PB02) at 1 Hz on embassy-time, and a line a second over the
//! virtual COM port (SERCOM1, PB00/PB01, 115,200 baud) with the time since
//! boot: the clocks, GPIO, the blocking UART and the time driver on the
//! PL10.

#![no_std]
#![no_main]
#![allow(clippy::used_underscore_binding, reason = "in code generated by embassy_executor::main")]

use core::fmt::Write;

use embassy_executor::Spawner;
use embassy_time::{Duration, Instant, Timer};
use panic_halt as _;
use pic32c_hal::gpio::{Level, Output};
use pic32c_hal::uart::{self, Uart};

struct Log<'d>(Uart<'d, pic32c_hal::mode::Blocking>);

impl Write for Log<'_> {
    fn write_str(&mut self, s: &str) -> core::fmt::Result {
        self.0.blocking_write(s.as_bytes());
        Ok(())
    }
}

#[embassy_executor::main]
async fn main(_spawner: Spawner) {
    let p = pic32cm_pl10_curiosity_nano::init();
    let mut led = Output::new(p.PB02, Level::High);
    let mut config = uart::Config::default();
    config.baudrate = 115_200;
    let mut log = Log(Uart::new_blocking(p.SERCOM1, p.PB00, p.PB01, config).unwrap());
    let _ = writeln!(log, "\r\npic32cm-pl10-curiosity-nano blink, CPU {} Hz", pic32c_hal::clocks::frequencies().map_or(0, |f| f.cpu()));
    let mut n = 0u32;
    loop {
        led.toggle();
        Timer::after(Duration::from_millis(500)).await;
        led.toggle();
        Timer::after(Duration::from_millis(500)).await;
        n += 1;
        let _ = writeln!(log, "tick {n}: {} ms since boot\r", Instant::now().as_millis());
    }
}
